content.text:
{
  "name": "Cobalt实验室激光器",
  "name_en": "Cobalt Laboratory Laser",
  "manufacturer": "Cobalt",
  "description": "一类用于实验室光学系统的可控激光光源，可开关激光输出并调节输出功率，常用于显微成像、荧光激发和一般光学实验中的稳定照明。",
  "description_en": "A controllable laboratory laser source with switchable emission and adjustable output power, commonly used for microscopy, fluorescence excitation, and general optical experiments requiring stable illumination.",
  "tag_hints": [
    "laser source",
    "optical excitation",
    "fluorescence microscopy",
    "adjustable output power",
    "lab illumination",
    "fault monitoring"
  ],
  "actions": [
    {
      "action_name": "auto-IsOn",
      "description": "获取激光输出是否开启。",
      "description_en": "Get whether the laser emission is on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "开启激光输出。",
      "description_en": "Turn on the laser emission."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭激光输出。",
      "description_en": "Turn off the laser emission."
    },
    {
      "action_name": "auto-SetPower",
      "description": "设置激光输出功率。",
      "description_en": "Set the laser output power."
    },
    {
      "action_name": "auto-GetPower",
      "description": "获取激光输出功率。",
      "description_en": "Get the laser output power."
    },
    {
      "action_name": "auto-checkfault",
      "description": "检查激光器故障状态或故障代码。",
      "description_en": "Check the laser fault status or fault code."
    }
  ]
}

